#include <iostream>
#include <unordered_map>
#include <string>
using namespace std;

class User {
public:
    string id;
    string name;
    User() {}
    User(string id, string name) : id(id), name(name) {}
};

class UserRepository {
public:
    virtual User* findById(string id) = 0;
    virtual void save(User user) = 0;
    virtual ~UserRepository() {}
};

class InMemoryUserRepository : public UserRepository {
private:
    unordered_map<string, User> store;
public:
    User* findById(string id) override {
        auto it = store.find(id);
        if (it == store.end()) return nullptr;
        return &it->second;
    }

    void save(User user) override {
        store[user.id] = user;
    }
};

int main() {
    UserRepository* repository = new InMemoryUserRepository();
    repository->save(User("u1", "Asha"));
    User* found = repository->findById("u1");
    cout << found->name << endl;
    delete repository;
    return 0;
}

