import java.util.HashMap;
import java.util.Map;

// The domain model, plain data, no data access logic here
class User {
    private String id;
    private String name;

    User(String id, String name) {
        this.id = id;
        this.name = name;
    }

    String getId() { return id; }
    String getName() { return name; }
}

// The contract. Business logic only ever depends on this interface.
interface UserRepository {
    User findById(String id);
    void save(User user);
}

// Implementation 1: a fast, disposable HashMap backed store, perfect for tests
class InMemoryUserRepository implements UserRepository {
    private Map<String, User> store = new HashMap<>();

    public User findById(String id) {
        return store.get(id);
    }

    public void save(User user) {
        store.put(user.getId(), user);
    }
}

// Implementation 2: stands in for a real, production database backed store
class SqlUserRepository implements UserRepository {
    // In a real system this would be a JDBC connection or an ORM session
    private Map<String, User> simulatedTable = new HashMap<>();

    public User findById(String id) {
        System.out.println("Running SQL: SELECT * FROM users WHERE id = " + id);
        return simulatedTable.get(id);
    }

    public void save(User user) {
        System.out.println("Running SQL: INSERT INTO users VALUES (" + user.getId() + ")");
        simulatedTable.put(user.getId(), user);
    }
}

// Business logic. Notice it only ever mentions UserRepository, never a concrete class.
class UserService {
    private UserRepository userRepository;

    UserService(UserRepository userRepository) {
        this.userRepository = userRepository;
    }

    void registerUser(String id, String name) {
        userRepository.save(new User(id, name));
    }

    String greetUser(String id) {
        User user = userRepository.findById(id);
        return "Welcome back, " + user.getName();
    }
}

public class Main {
    public static void main(String[] args) {
        // Wired with the in memory implementation, useful for tests and local runs
        UserService serviceWithMemory = new UserService(new InMemoryUserRepository());
        serviceWithMemory.registerUser("u1", "Asha");
        System.out.println(serviceWithMemory.greetUser("u1"));

        // Same UserService class, swapped to a database backed implementation.
        // Not one line inside UserService changed.
        UserService serviceWithSql = new UserService(new SqlUserRepository());
        serviceWithSql.registerUser("u2", "Raj");
        System.out.println(serviceWithSql.greetUser("u2"));
    }
}

