#include <unordered_map>
#include <string>
using namespace std;

// The domain model, plain data, no data access logic here
class User {
public:
    string id;
    string name;
    User() {}
    User(string id, string name) : id(id), name(name) {}
};

// The contract. Business logic only ever depends on this interface.
class UserRepository {
public:
    virtual User* findById(string id) = 0;
    virtual void save(User user) = 0;
    virtual ~UserRepository() {}
};

// Implementation 1: a fast, disposable HashMap backed store, perfect for tests
class InMemoryUserRepository : public UserRepository {
private:
    unordered_map<string, User> store;
public:
    User* findById(string id) override {
        auto it = store.find(id);
        if (it == store.end()) return nullptr;
        return &it->second;
    }

    void save(User user) override {
        store[user.id] = user;
    }
};

// Implementation 2: stands in for a real, production database backed store
class SqlUserRepository : public UserRepository {
private:
    // In a real system this would be a database connection or an ORM session
    unordered_map<string, User> simulatedTable;
public:
    User* findById(string id) override {
        cout << "Running SQL: SELECT * FROM users WHERE id = " << id << endl;
        auto it = simulatedTable.find(id);
        if (it == simulatedTable.end()) return nullptr;
        return &it->second;
    }

    void save(User user) override {
        cout << "Running SQL: INSERT INTO users VALUES (" << user.id << ")" << endl;
        simulatedTable[user.id] = user;
    }
};

